  CONSTRAINT `akses_menu_level_foreign` FOREIGN KEY (`level_id`) REFERENCES `role_user` (`level_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `akses_menu_menu_id_foreign` FOREIGN KEY (`menu_id`) REFERENCES `tb_menu` (`menu_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

