/*Table structure for table `closing_log` */

DROP TABLE IF EXISTS `closing_log`;

CREATE TABLE `closing_log` (
  `closing_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `toko_id` varchar(5) NOT NULL,
  `periode` date NOT NULL,
  `mode` enum('WEB','CLI','RECLOSE') NOT NULL DEFAULT 'WEB',
  `status` enum('SUCCESS','ERROR') NOT NULL,
