/*Table structure for table `customer` */

DROP TABLE IF EXISTS `customer`;

CREATE TABLE `customer` (
  `cust_id` varchar(7) NOT NULL,
  `nama` varchar(200) NOT NULL,
  `alamat` varchar(150) NOT NULL,
  `kontak` varchar(13) NOT NULL,
  `tgl_daftar` date NOT NULL,
  `max_faktur` int(3) NOT NULL DEFAULT 3,
  `poin` int(6) NOT NULL DEFAULT 0,
  `harga_grosir` char(1) NOT NULL DEFAULT 'N',
  `margin_grosir` decimal(5,2) NOT NULL DEFAULT 0.00,
  `updid` varchar(50) DEFAULT NULL,
  `updtime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`cust_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

