/*Table structure for table `kas_mutasi` */

DROP TABLE IF EXISTS `kas_mutasi`;

CREATE TABLE `kas_mutasi` (
  `kas_id` int(11) NOT NULL AUTO_INCREMENT,
  `tanggal` datetime NOT NULL DEFAULT current_timestamp(),
  `toko_id` varchar(5) NOT NULL,
  `nama_akun` varchar(50) DEFAULT NULL,
  `tipe_mutasi` enum('OPERASIONAL','PINDAH_SALDO') NOT NULL DEFAULT 'OPERASIONAL',
  `saldo_target` enum('TOKO','PEMILIK') DEFAULT 'TOKO',
  `saldo_channel` enum('CASH','NONCASH') NOT NULL DEFAULT 'CASH',
  `saldo_asal` enum('CASH','NONCASH') DEFAULT NULL,
  `saldo_asal_target` enum('TOKO','PEMILIK') DEFAULT NULL,
  `saldo_tujuan` enum('CASH','NONCASH') DEFAULT NULL,
  `saldo_tujuan_target` enum('TOKO','PEMILIK') DEFAULT NULL,
  `nominal` int(11) NOT NULL DEFAULT 0,
  `karyawan_id` varchar(20) NOT NULL,
  `keterangan` varchar(150) DEFAULT NULL,
  `updid` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`kas_id`),
  KEY `idx_kas_mutasi_1` (`toko_id`,`tanggal`),
  KEY `idx_kas_mutasi_2` (`nama_akun`,`tanggal`),
  KEY `idx_kas_mutasi_3` (`karyawan_id`,`tanggal`),
  KEY `idx_kas_mutasi_4` (`tipe_mutasi`,`saldo_channel`,`tanggal`),
  CONSTRAINT `fk_kas_akun` FOREIGN KEY (`nama_akun`) REFERENCES `akun_kas` (`nama_akun`) ON UPDATE CASCADE,
  CONSTRAINT `fk_kas_toko` FOREIGN KEY (`toko_id`) REFERENCES `toko` (`toko_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_kas_user` FOREIGN KEY (`karyawan_id`) REFERENCES `tb_user` (`karyawan_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

