/*Table structure for table `pembelian` */

DROP TABLE IF EXISTS `pembelian`;

CREATE TABLE `pembelian` (
  `toko_id` varchar(5) NOT NULL,
  `beli_id` varchar(15) NOT NULL,
  `tanggal` date NOT NULL,
  `supco` varchar(10) NOT NULL,
  `invoice` varchar(50) NOT NULL,
  `total_gross` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_bayar` decimal(15,2) NOT NULL DEFAULT 0.00,
  `sisa_bayar` decimal(15,2) NOT NULL DEFAULT 0.00,
  `is_kredit` tinyint(1) NOT NULL DEFAULT 0,
  `status_nota` enum('PO','TERIMA') NOT NULL DEFAULT 'PO',
  `status_bayar` enum('BELUM','CICIL','LUNAS') NOT NULL DEFAULT 'BELUM',
  `jatuh_tempo` date DEFAULT NULL,
  `username` varchar(50) NOT NULL,
  `keterangan` varchar(250) DEFAULT NULL,
  `updtime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`toko_id`,`beli_id`),
  KEY `idx_monitoring_hutang` (`toko_id`,`is_kredit`,`status_bayar`,`jatuh_tempo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pembelian` */

/*Table structure for table `pembelian_detail` */

DROP TABLE IF EXISTS `pembelian_detail`;

CREATE TABLE `pembelian_detail` (
  `toko_id` varchar(5) NOT NULL,
  `beli_id` varchar(15) NOT NULL,
  `seq_no` int(3) NOT NULL,
  `kode_item` varchar(7) NOT NULL,
  `qty_beli` float NOT NULL,
  `sat_id` varchar(20) NOT NULL,
  `qty_konversi` float NOT NULL DEFAULT 1,
  `qty_stock` float NOT NULL,
  `price` decimal(15,2) NOT NULL,
  `gross` decimal(15,2) NOT NULL,
  PRIMARY KEY (`toko_id`,`beli_id`,`seq_no`),
  CONSTRAINT `fk_pembelian_detail` FOREIGN KEY (`toko_id`, `beli_id`) REFERENCES `pembelian` (`toko_id`, `beli_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pembelian_detail` */

/*Table structure for table `pembelian_pembayaran` */

DROP TABLE IF EXISTS `pembelian_pembayaran`;

CREATE TABLE `pembelian_pembayaran` (
  `bayar_id` int(11) NOT NULL AUTO_INCREMENT,
  `toko_id` varchar(5) NOT NULL,
  `beli_id` varchar(15) NOT NULL,
  `retur_id` varchar(15) DEFAULT NULL,
  `tanggal_bayar` datetime NOT NULL,
  `cara_bayar` enum('TUNAI','TRANSFER','POTONGAN RETUR') NOT NULL,
  `jumlah_bayar` decimal(15,2) NOT NULL,
  `bank_nama` varchar(50) DEFAULT NULL,
  `rekening_no` varchar(50) DEFAULT NULL,
  `username` varchar(50) NOT NULL,
  PRIMARY KEY (`bayar_id`),
  KEY `fk_pembayaran_beli` (`toko_id`,`beli_id`),
  KEY `idx_pembayaran_retur` (`toko_id`,`retur_id`),
  CONSTRAINT `fk_pembayaran_beli` FOREIGN KEY (`toko_id`, `beli_id`) REFERENCES `pembelian` (`toko_id`, `beli_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pembelian_pembayaran` */

/*Table structure for table `pembelian_retur` */

DROP TABLE IF EXISTS `pembelian_retur`;

CREATE TABLE `pembelian_retur` (
  `toko_id` varchar(5) NOT NULL,
  `retur_id` varchar(15) NOT NULL,
  `beli_id` varchar(15) DEFAULT NULL,
  `tanggal` date NOT NULL,
  `supco` varchar(10) NOT NULL,
  `total_retur` decimal(15,2) NOT NULL DEFAULT 0.00,
  `settlement_mode` enum('POTONG_HUTANG','CASHBACK') NOT NULL DEFAULT 'POTONG_HUTANG',
  `status_retur` enum('DRAFT','SELESAI') NOT NULL DEFAULT 'DRAFT',
  `username` varchar(50) NOT NULL,
  `keterangan` varchar(250) DEFAULT NULL,
  `updtime` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`toko_id`,`retur_id`),
  KEY `idx_retur_supplier` (`toko_id`,`supco`,`tanggal`),
  KEY `fk_retur_ke_pembelian` (`toko_id`,`beli_id`),
  CONSTRAINT `fk_retur_ke_pembelian` FOREIGN KEY (`toko_id`, `beli_id`) REFERENCES `pembelian` (`toko_id`, `beli_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pembelian_retur` */

/*Table structure for table `pembelian_retur_detail` */

DROP TABLE IF EXISTS `pembelian_retur_detail`;

CREATE TABLE `pembelian_retur_detail` (
  `toko_id` varchar(5) NOT NULL,
  `retur_id` varchar(15) NOT NULL,
  `seq_no` int(3) NOT NULL,
  `kode_item` varchar(7) NOT NULL,
  `qty_retur` float NOT NULL DEFAULT 0,
  `sat_id` varchar(20) NOT NULL,
  `qty_konversi` float NOT NULL DEFAULT 1,
  `qty_stok` float NOT NULL,
  `price` decimal(15,2) NOT NULL,
  `gross_retur` decimal(15,2) NOT NULL,
  PRIMARY KEY (`toko_id`,`retur_id`,`seq_no`),
  CONSTRAINT `fk_retur_detail` FOREIGN KEY (`toko_id`, `retur_id`) REFERENCES `pembelian_retur` (`toko_id`, `retur_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

