/*Table structure for table `prodmast_hapus` */

DROP TABLE IF EXISTS `prodmast_hapus`;

CREATE TABLE `prodmast_hapus` (
  `kode_item` varchar(7) NOT NULL,
  `barcode` varchar(20) NOT NULL,
  `nama_item` varchar(100) NOT NULL,
  `kat_id` varchar(50) NOT NULL,
  `keterangan` varchar(100) NOT NULL,
  `supco` varchar(7) DEFAULT NULL,
  `updid` varchar(100) DEFAULT NULL,
  `updtime` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

