/*Table structure for table `prodmast_satuan` */

DROP TABLE IF EXISTS `prodmast_satuan`;

CREATE TABLE `prodmast_satuan` (
  `kode_item` varchar(7) NOT NULL,
  `sat_id` varchar(50) NOT NULL,
  `qty_konversi` float NOT NULL DEFAULT 1,
  PRIMARY KEY (`kode_item`,`sat_id`),
  KEY `fk_satuan_item` (`sat_id`),
  CONSTRAINT `fk_kode_item` FOREIGN KEY (`kode_item`) REFERENCES `prodmast` (`kode_item`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_satuan_item` FOREIGN KEY (`sat_id`) REFERENCES `satuan` (`sat_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

