/*Table structure for table `prodmast_store` */

DROP TABLE IF EXISTS `prodmast_store`;

CREATE TABLE `prodmast_store` (
  `toko_id` varchar(4) NOT NULL,
  `kode_item` varchar(7) NOT NULL,
  `sat_id` varchar(50) NOT NULL,
  `supco` varchar(10) DEFAULT NULL,
  `harga_pokok` int(11) DEFAULT 0,
  `harga_jual` int(11) DEFAULT NULL,
  `target_psn_margin` float DEFAULT 0,
  `status_item` enum('Y','N') NOT NULL DEFAULT 'Y',
  `last_so` date DEFAULT NULL,
  `last_beli` date DEFAULT NULL,
  `last_jual` date DEFAULT NULL,
  `updid` varchar(100) DEFAULT '',
  `updtime` datetime DEFAULT NULL,
  PRIMARY KEY (`toko_id`,`kode_item`,`sat_id`),
  KEY `fk_store_item` (`kode_item`,`sat_id`),
  KEY `idx_store_supplier` (`toko_id`,`supco`),
  CONSTRAINT `fk_store_item` FOREIGN KEY (`kode_item`, `sat_id`) REFERENCES `prodmast_satuan` (`kode_item`, `sat_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

