/*Table structure for table `retur_jual` */

DROP TABLE IF EXISTS `retur_jual`;

CREATE TABLE `retur_jual` (
  `rj_id` varchar(20) NOT NULL,
  `toko_id` varchar(5) NOT NULL,
  `jual_id` varchar(20) NOT NULL,
  `tanggal` datetime NOT NULL,
  `gross_retur` decimal(15,2) NOT NULL DEFAULT 0.00,
  `updid` varchar(100) DEFAULT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`rj_id`,`toko_id`),
  UNIQUE KEY `uniq_retur_jual_once` (`toko_id`,`jual_id`),
  KEY `idx_retur_jual_1` (`toko_id`,`tanggal`),
  KEY `fk_retur_jual_penjualan` (`jual_id`,`toko_id`),
  CONSTRAINT `fk_retur_jual_penjualan` FOREIGN KEY (`jual_id`, `toko_id`) REFERENCES `penjualan` (`jual_id`, `toko_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `retur_jual` */

/*Table structure for table `retur_jual_detail` */

DROP TABLE IF EXISTS `retur_jual_detail`;

CREATE TABLE `retur_jual_detail` (
  `rj_id` varchar(20) NOT NULL,
  `toko_id` varchar(5) NOT NULL,
  `seq_no` int(3) NOT NULL,
  `kode_item` varchar(50) NOT NULL,
  `sat_id` varchar(50) NOT NULL,
  `qty_jual` float NOT NULL DEFAULT 0,
  `qty_retur` float NOT NULL DEFAULT 0,
  `qty_konversi` float NOT NULL DEFAULT 1,
  `qty_stock` float NOT NULL DEFAULT 0,
  `price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gross_retur` decimal(15,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`rj_id`,`toko_id`,`seq_no`),
  CONSTRAINT `fk_retur_jual_detail` FOREIGN KEY (`rj_id`, `toko_id`) REFERENCES `retur_jual` (`rj_id`, `toko_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `retur_jual_detail` */

/*Table structure for table `role_user` */

DROP TABLE IF EXISTS `role_user`;

CREATE TABLE `role_user` (
  `level_id` varchar(100) NOT NULL,
  `level_name` varchar(100) NOT NULL,
  PRIMARY KEY (`level_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `role_user` */

