/*Table structure for table `saldo_cash_harian` */

DROP TABLE IF EXISTS `saldo_cash_harian`;

CREATE TABLE `saldo_cash_harian` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `toko_id` varchar(10) NOT NULL,
  `tanggal` date NOT NULL,
  `saldo_toko_awal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `saldo_pemilik_awal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `pos_tunai` decimal(15,2) NOT NULL DEFAULT 0.00,
  `pos_transfer` decimal(15,2) NOT NULL DEFAULT 0.00,
  `pos_qris` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bayar_piutang_tunai` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bayar_piutang_transfer` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bayar_piutang_qris` decimal(15,2) NOT NULL DEFAULT 0.00,
  `kas_masuk_tunai` decimal(15,2) NOT NULL DEFAULT 0.00,
  `kas_masuk_noncash` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tarik_pemilik_ke_toko` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bayar_hutang_tunai` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bayar_hutang_transfer` decimal(15,2) NOT NULL DEFAULT 0.00,
  `kas_keluar_tunai` decimal(15,2) NOT NULL DEFAULT 0.00,
  `kas_keluar_noncash` decimal(15,2) NOT NULL DEFAULT 0.00,
  `deposit_toko_ke_pemilik` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tarik_keuntungan_toko` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tarik_keuntungan_pemilik` decimal(15,2) NOT NULL DEFAULT 0.00,
  `saldo_toko_akhir` decimal(15,2) NOT NULL DEFAULT 0.00,
  `saldo_pemilik_akhir` decimal(15,2) NOT NULL DEFAULT 0.00,
  `closed_at` datetime DEFAULT NULL,
  `closed_by` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_toko_tanggal` (`toko_id`,`tanggal`),
  KEY `idx_tanggal` (`tanggal`)
) ENGINE=InnoDB AUTO_INCREMENT=250 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

