/*Table structure for table `stmast` */

DROP TABLE IF EXISTS `stmast`;

CREATE TABLE `stmast` (
  `toko_id` varchar(5) NOT NULL,
  `KODE_ITEM` varchar(8) NOT NULL DEFAULT '',
  `ACOST` decimal(12,0) NOT NULL DEFAULT 0,
  `QTY` float NOT NULL DEFAULT 0,
  `RP_SALDO_AKH` decimal(12,0) NOT NULL DEFAULT 0,
  `BEGBAL` float NOT NULL DEFAULT 0,
  `PKM` decimal(12,0) NOT NULL DEFAULT 0,
  `spd` decimal(15,4) NOT NULL DEFAULT 0.0000,
  `BELI` float NOT NULL DEFAULT 0,
  `RETUR_BELI` decimal(12,0) NOT NULL DEFAULT 0,
  `JUAL` float NOT NULL DEFAULT 0,
  `RETUR_JUAL` decimal(12,0) NOT NULL DEFAULT 0,
  `ADJ` float NOT NULL DEFAULT 0,
  `UPDID` varchar(100) DEFAULT NULL,
  `UPDTIME` datetime DEFAULT NULL,
  PRIMARY KEY (`toko_id`,`KODE_ITEM`),
  KEY `fk_stok_produk` (`KODE_ITEM`),
  CONSTRAINT `fk_stok_produk` FOREIGN KEY (`KODE_ITEM`) REFERENCES `prodmast` (`kode_item`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

